"""Independent legacy/grid archive bytes are never generated by the native encoder."""
import hashlib
import importlib.util
import json
from pathlib import Path
import subprocess
import sys
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('raw_grid_archive_oracle',ROOT/'tools/reference_raw_grid_archive.py')
reference=importlib.util.module_from_spec(spec);spec.loader.exec_module(reference)

def test_independent_qra1_qra2_and_native_table_regenerate():
    data=reference.reference()
    assert json.loads((ROOT/'tests/fixtures/raw-grid-archive-v1/reference.json').read_text(encoding='utf-8'))==data
    assert (ROOT/'cpp/tests/raw_grid_archive_reference.hpp').read_bytes()==reference.native_header(data).encode('utf-8')
    assert [c['name'] for c in data['cases']]==['legacy','grid']

def test_reference_versions_checksums_and_distinct_input_identities():
    data=reference.reference()
    for version,c in enumerate(data['cases'],1):
        raw=bytes.fromhex(c['bytes_hex']);assert raw[:4]==b'QRA'+bytes([version])
        assert hashlib.sha256(raw[:-64]).hexdigest().encode()==raw[-64:]
        assert hashlib.sha256(raw).hexdigest()==c['sha256']
    assert data['cases'][0]['input_sha256']!=data['cases'][1]['input_sha256']
    assert 'Synthetic' in data['scope']

def test_archive_generation_refuses_existing_outputs(tmp_path):
    data=tmp_path/'reference.json';header=tmp_path/'native.hpp'
    cmd=[sys.executable,'-I',str(ROOT/'tools/reference_raw_grid_archive.py'),'--output',str(data),'--native-header',str(header)]
    p=subprocess.run(cmd,capture_output=True);assert p.returncode==0,p.stderr
    saved=data.read_bytes(),header.read_bytes();p=subprocess.run(cmd,capture_output=True)
    assert p.returncode==2 and (data.read_bytes(),header.read_bytes())==saved
